import DOMPurify from 'dompurify'

/**
 * Checks if a string contains HTML tags or formatting
 */
export function hasHtmlFormatting(str: string): boolean {
  if (!str || typeof str !== 'string') return false
  const formattingRegex = /<\s*(?:b|strong|i|em|u|s|strike|del|mark|span|p|h[1-6]|ul|ol|li|a|table|tr|td|th|blockquote|pre|code|sub|sup|font)\b[^>]*>|<\s*br\s*\/?>/i
  const styleRegex = /\b(?:style|color)\s*=/i
  return formattingRegex.test(str) || styleRegex.test(str)
}

/**
 * Detects if clipboard HTML is generated by a browser PDF viewer (PDF.js, Chrome PDF Viewer, etc.)
 */
export function isPdfHtml(html: string): boolean {
  if (!html || typeof html !== 'string') return false
  return (
    html.includes('textLayer') ||
    html.includes('data-page-number') ||
    html.includes('class="page"') ||
    /position:\s*absolute/i.test(html) ||
    /font-family:[^;]*pdf/i.test(html)
  )
}

/**
 * Detects if text contains PDF copying patterns or structured formatting:
 * - Hyphenation across linebreaks (e.g. "infor-\nmación")
 * - Bullet characters (•, ●, ▪, ■, ►, ▸, ○, –, —)
 * - Numbered lists (1. Item, 2. Item)
 * - Tabular columns (separated by tabs or 2+ spaces)
 * - Paragraph lines broken without terminating punctuation
 */
export function isPdfOrStructuredText(text: string): boolean {
  if (!text || typeof text !== 'string') return false
  const trimmed = text.trim()
  if (trimmed.length < 10) return false

  // 1. Hyphenated line breaks: "infor-\nmación"
  if (/[a-záéíóúñA-ZÁÉÍÓÚÑ]{2,}-\s*\n\s*[a-záéíóúñA-ZÁÉÍÓÚÑ]{2,}/i.test(trimmed)) {
    return true
  }

  // 2. Unicode bullet characters at line start
  if (/(?:^|\n)\s*[•●▪■►▸○–—]\s+/u.test(trimmed)) {
    return true
  }

  // 3. Numbered list patterns: "1. Item" or "1) Item"
  if (/(?:^|\n)\s*\d+[\.\)]\s+[A-ZÁÉÍÓÚÑa-záéíóúñ]/i.test(trimmed)) {
    return true
  }

  // 4. Tabular data with multiple tabs or multi-space columns across lines
  if (/(?:^|\n)[^\n\t]+(?:\t|\x20{2,})[^\n\t]+\n[^\n\t]+(?:\t|\x20{2,})[^\n\t]+/.test(trimmed)) {
    return true
  }

  // 5. Lines wrapped without punctuation (classic PDF wrapped lines)
  const lines = trimmed.split('\n').map((l) => l.trim()).filter(Boolean)
  if (lines.length >= 3) {
    const linesWithoutPunctuation = lines.filter((l) => l.length > 25 && !/[.?!:;]$/.test(l))
    if (linesWithoutPunctuation.length >= 2) {
      return true
    }
  }

  return false
}

/**
 * Formats plain text copied from a PDF reader (Adobe Acrobat, Foxit, Sumatra, Chrome PDF, Preview)
 * into semantic, rich HTML:
 * - Un-breaks wrapped lines inside sentences while keeping paragraph breaks
 * - Fixes hyphenated words across line ends ("conser-\nvación" -> "conservación")
 * - Converts bullet points (•, ●, ▪, etc.) to <ul><li>
 * - Converts numbered items (1., 2.) to <ol><li>
 * - Converts multi-column lines to <table>
 * - Detects headings and labels
 * - Turns URLs into clickable links
 */
export function formatPdfOrStructuredText(text: string): string {
  if (!text || typeof text !== 'string') return ''

  // 1. Normalize line endings
  let normalized = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n')

  // 2. Fix hyphenation across line breaks: "consis-\ntente" -> "consistente"
  normalized = normalized.replace(/([a-záéíóúñA-ZÁÉÍÓÚÑ]{2,})-\s*\n\s*([a-záéíóúñA-ZÁÉÍÓÚÑ]{2,})/g, '$1$2')

  // 3. Auto-link URLs helper
  const linkify = (str: string) => {
    return str.replace(
      /(https?:\/\/[^\s<>"'`]+|www\.[^\s<>"'`]+)/g,
      (url) => {
        const href = url.startsWith('http') ? url : `https://${url}`
        return `<a href="${href}" target="_blank" rel="noopener noreferrer">${url}</a>`
      }
    )
  }

  // 4. Helper to escape minimal HTML characters before adding semantic tags
  const escapeHtml = (str: string) => {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
  }

  // 5. Check if lines are part of a table (tab-separated or multi-space columns)
  const isTableLine = (line: string): boolean => {
    const trimmed = line.trim()
    if (!trimmed) return false
    const parts = trimmed.split(/\t+|\x20{2,}/)
    return parts.length >= 2
  }

  const rawLines = normalized.split('\n')
  const htmlParts: string[] = []

  let currentListType: 'ul' | 'ol' | null = null
  let currentTableRows: string[][] = []
  let currentParagraphLines: string[] = []

  const flushParagraph = () => {
    if (currentParagraphLines.length > 0) {
      const fullText = currentParagraphLines.join(' ')
      const trimmed = fullText.trim()
      if (
        trimmed.length > 0 &&
        trimmed.length < 90 &&
        !/[.?!;]$/.test(trimmed) &&
        (
          (trimmed.length > 3 && trimmed === trimmed.toUpperCase() && /[A-ZÁÉÍÓÚÑ]/.test(trimmed)) ||
          /^(?:cap[íi]tulo|secci[oó]n|tema|unidad|parte|chapter|section)\s+\d+/i.test(trimmed) ||
          /^(?:[IVXLCDM]+\.|\d+(\.\d+)*)\s+[A-ZÁÉÍÓÚÑ]/.test(trimmed) ||
          trimmed.endsWith(':')
        )
      ) {
        if (trimmed.endsWith(':')) {
          htmlParts.push(`<p><strong>${linkify(escapeHtml(trimmed))}</strong></p>`)
        } else {
          htmlParts.push(`<h3>${linkify(escapeHtml(trimmed))}</h3>`)
        }
      } else {
        htmlParts.push(`<p>${linkify(escapeHtml(fullText))}</p>`)
      }
      currentParagraphLines = []
    }
  }

  const flushList = () => {
    if (currentListType) {
      htmlParts.push(`</${currentListType}>`)
      currentListType = null
    }
  }

  const flushTable = () => {
    if (currentTableRows.length > 0) {
      let tableHtml = '<table class="border-collapse border border-zinc-500/30 my-2 w-full text-left text-sm">'
      const headerRow = currentTableRows[0]
      tableHtml += '<thead><tr>'
      for (const cell of headerRow) {
        tableHtml += `<th class="border border-zinc-500/30 p-1.5 font-semibold bg-black/10 dark:bg-white/10">${linkify(escapeHtml(cell))}</th>`
      }
      tableHtml += '</tr></thead><tbody>'
      for (let i = 1; i < currentTableRows.length; i++) {
        tableHtml += '<tr>'
        for (const cell of currentTableRows[i]) {
          tableHtml += `<td class="border border-zinc-500/30 p-1.5">${linkify(escapeHtml(cell))}</td>`
        }
        tableHtml += '</tr>'
      }
      tableHtml += '</tbody></table>'
      htmlParts.push(tableHtml)
      currentTableRows = []
    }
  }

  const flushAll = () => {
    flushParagraph()
    flushList()
    flushTable()
  }

  for (let i = 0; i < rawLines.length; i++) {
    const rawLine = rawLines[i]
    const trimmed = rawLine.trim()

    // Blank line -> Paragraph separator
    if (!trimmed) {
      flushAll()
      continue
    }

    // Check for bullet list item: •, ●, ▪, ■, ►, ▸, ○, –, —, *, -
    const bulletMatch = trimmed.match(/^([•●▪■►▸○–—*]|-)\s+(.*)$/)
    if (bulletMatch) {
      flushParagraph()
      flushTable()
      if (currentListType !== 'ul') {
        flushList()
        htmlParts.push('<ul class="list-disc pl-5 my-1.5 space-y-0.5">')
        currentListType = 'ul'
      }
      htmlParts.push(`<li>${linkify(escapeHtml(bulletMatch[2]))}</li>`)
      continue
    }

    // Check for numbered list item: 1. Item, 1) Item, a. Item, a) Item
    const numMatch = trimmed.match(/^(\d{1,3}|[a-zA-Z])[\.\)]\s+(.*)$/)
    if (numMatch) {
      flushParagraph()
      flushTable()
      if (currentListType !== 'ol') {
        flushList()
        htmlParts.push('<ol class="list-decimal pl-5 my-1.5 space-y-0.5">')
        currentListType = 'ol'
      }
      htmlParts.push(`<li>${linkify(escapeHtml(numMatch[2]))}</li>`)
      continue
    }

    // Check for table row (if next or previous line is also table row)
    const isThisTable = isTableLine(rawLine)
    const isPrevTable = currentTableRows.length > 0
    const isNextTable = i + 1 < rawLines.length && isTableLine(rawLines[i + 1])

    if (isThisTable && (isPrevTable || isNextTable)) {
      flushParagraph()
      flushList()
      const parts = trimmed.split(/\t+|\x20{2,}/).map((s) => s.trim()).filter(Boolean)
      currentTableRows.push(parts)
      continue
    } else if (currentTableRows.length > 0) {
      flushTable()
    }

    // Check for blockquote: "> quote" or "« quote »"
    const quoteMatch = trimmed.match(/^(?:>|»|“|")\s*(.*?)(?:”|"|«)?$/)
    if (trimmed.startsWith('>') || (trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length > 25)) {
      flushAll()
      const quoteText = quoteMatch ? quoteMatch[1] : trimmed
      htmlParts.push(`<blockquote class="border-l-2 pl-3 italic border-zinc-400 my-1.5">${linkify(escapeHtml(quoteText))}</blockquote>`)
      continue
    }

    // Regular text line
    flushList()
    flushTable()

    if (currentParagraphLines.length > 0) {
      const lastLine = currentParagraphLines[currentParagraphLines.length - 1]
      if (
        /[.?!:]$/.test(lastLine) &&
        trimmed.length < 50 &&
        (trimmed === trimmed.toUpperCase() || /^[A-ZÁÉÍÓÚÑ]/.test(trimmed))
      ) {
        flushParagraph()
        currentParagraphLines.push(trimmed)
      } else {
        currentParagraphLines.push(trimmed)
      }
    } else {
      currentParagraphLines.push(trimmed)
    }
  }

  flushAll()

  const result = htmlParts.join('')
  return sanitizeHtmlContent(result)
}

/**
 * Cleans PDF HTML or converts PDF plain text to structured HTML
 */
export function cleanPdfHtml(html: string, textFallback?: string): string {
  if (!html && !textFallback) return ''

  // If textFallback has strong PDF text structure, formatPdfOrStructuredText produces
  // significantly better semantic HTML (real <ul>, <ol>, <h3>, <table>, <p>) than
  // browser PDF viewers' fragmented absolute position spans and br tags
  if (textFallback && isPdfOrStructuredText(textFallback)) {
    return formatPdfOrStructuredText(textFallback)
  }

  let cleaned = html
  // Fix PDF line-break hyphenation
  cleaned = cleaned.replace(/([a-záéíóúñA-ZÁÉÍÓÚÑ]{2,})-\s*(?:<br\s*\/?>|<\/span><span>)\s*([a-záéíóúñA-ZÁÉÍÓÚÑ]{2,})/gi, '$1$2')
  
  // Remove absolute positioning and transforms from browser PDF viewers
  cleaned = cleaned.replace(/position:\s*absolute;?/gi, '')
  cleaned = cleaned.replace(/transform:[^;]*;?/gi, '')

  return cleanPastedHtml(cleaned)
}

/**
 * Cleans pasted HTML from clipboard (Word, Google Docs, web pages)
 * while strictly preserving text formatting (bold, italic, underline, strike,
 * colors, background highlights, links, headings, lists, tables, code, etc.)
 */
export function cleanPastedHtml(html: string): string {
  if (!html || typeof html !== 'string') return ''

  let cleaned = html

  // 1. Remove Google Docs internal wrapper if present
  // e.g. <b style="font-weight:normal;" id="docs-internal-guid-...">
  cleaned = cleaned.replace(/<b\s+style="font-weight:\s*normal;?"\s+id="docs-internal-guid-[^"]*">([\s\S]*?)<\/b>/gi, '$1')

  // 2. Remove Microsoft Office / Word comment blocks, meta tags & Office namespaces
  cleaned = cleaned.replace(/<!--[\s\S]*?-->/gi, '')
  cleaned = cleaned.replace(/<\/?o:[^>]*>/gi, '')
  cleaned = cleaned.replace(/<\/?w:[^>]*>/gi, '')
  cleaned = cleaned.replace(/<xml>[\s\S]*?<\/xml>/gi, '')
  cleaned = cleaned.replace(/<meta[^>]*>/gi, '')
  cleaned = cleaned.replace(/<link[^>]*>/gi, '')
  cleaned = cleaned.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')

  // 3. Sanitize HTML allowing safe formatting tags & attributes
  return sanitizeHtmlContent(cleaned)
}

/**
 * Sanitizes HTML content for safe rendering in notes and cards
 */
export function sanitizeHtmlContent(html: string): string {
  if (!html || typeof html !== 'string') return ''

  const sanitized = DOMPurify.sanitize(html, {
    ALLOWED_TAGS: [
      'p', 'br', 'span', 'div', 'b', 'strong', 'i', 'em', 'u', 's', 'strike', 'del',
      'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
      'ul', 'ol', 'li', 'blockquote', 'pre', 'code', 'mark',
      'table', 'thead', 'tbody', 'tr', 'th', 'td',
      'a', 'img', 'sub', 'sup', 'hr'
    ],
    ALLOWED_ATTR: [
      'href', 'target', 'rel', 'style', 'class', 'title', 'src', 'alt', 'width', 'height', 'align', 'color'
    ],
    ALLOW_DATA_ATTR: true
  })

  // Ensure all links open in a new tab with noopener noreferrer
  return sanitized.replace(/<a\b(?![^>]*\btarget=)([^>]*?)>/gi, '<a target="_blank" rel="noopener noreferrer"$1>')
}
